//Generated by AI

using TMPro;
using UnityEngine;
using UnityEngine.UI;
using System.Collections;

// Controls the display and automatic hiding of tutorial subtitles.
public class SubtitleController : MonoBehaviour
{
    [Header("Subtitle References")]
    [SerializeField] private TMP_Text subtitleText;
    [SerializeField] private Image subtitleBackground;

    // Displays a subtitle and starts its automatic hiding process.
    public void ShowSubtitle(string message)
    {
        // Prevent overlapping subtitle routines.
        StopAllCoroutines();

        subtitleText.text = message;

        // Set the subtitle background opacity to 70%.
        Color bg = subtitleBackground.color;
        bg.a = 0.7f;
        subtitleBackground.color = bg;

        StartCoroutine(HideSubtitle());
    }

    // Updates the subtitle font size.
    public void SetTextSize(float size)
    {
        subtitleText.fontSize = size;
    }

    // Hides the subtitle after three seconds.
    private IEnumerator HideSubtitle()
    {
        yield return new WaitForSeconds(3f);

        subtitleText.text = "";

        // Make the subtitle background fully transparent.
        Color bg = subtitleBackground.color;
        bg.a = 0f;
        subtitleBackground.color = bg;
    }
}
